import { z } from "zod";
import { readSessionState } from "../core/session.js";
import { SimpleCLI } from "affordance";
import {
  pageOption,
  sessionOption,
  withRequiredSession
} from "./shared.js";
import { DaemonClient } from "../core/daemon/ipc.js";
import { renderSnapshot } from "../../shared/snapshot/render-snapshot.js";
const FALLBACK_SNAPSHOT_VIEWPORT = { width: 1280, height: 800 };
function isZeroViewport(value) {
  return typeof value === "number" && value <= 0;
}
function shouldForceSnapshotViewport(metrics) {
  return isZeroViewport(metrics.configuredWidth) || isZeroViewport(metrics.configuredHeight) || isZeroViewport(metrics.innerWidth) || isZeroViewport(metrics.innerHeight);
}
function isZeroWidthScreenshotError(error) {
  return error instanceof Error && error.message.includes("Cannot take screenshot with 0 width");
}
async function readSnapshotViewportMetrics(page) {
  const configuredViewport = page.viewportSize();
  let innerWidth = null;
  let innerHeight = null;
  try {
    const innerViewport = await page.evaluate(() => ({
      width: window.innerWidth,
      height: window.innerHeight
    }));
    innerWidth = innerViewport.width;
    innerHeight = innerViewport.height;
  } catch {
  }
  return {
    configuredWidth: configuredViewport?.width ?? null,
    configuredHeight: configuredViewport?.height ?? null,
    innerWidth,
    innerHeight
  };
}
function resolveSnapshotViewport(session, logger) {
  const state = readSessionState(session, logger);
  if (state?.viewport) {
    logger.info("screenshot-viewport-from-session-state", {
      session,
      viewport: state.viewport
    });
    return state.viewport;
  }
  logger.info("screenshot-viewport-fallback", {
    session,
    reason: "no viewport in session state",
    viewport: FALLBACK_SNAPSHOT_VIEWPORT
  });
  return FALLBACK_SNAPSHOT_VIEWPORT;
}
async function forceSnapshotViewport(page, viewport, logger, session, pageId, reason) {
  await page.setViewportSize(viewport);
  logger.warn("screenshot-viewport-forced", {
    session,
    pageId,
    reason,
    viewport
  });
}
async function runCompactSnapshot(args) {
  if (!args.daemonSocketPath) {
    throw new Error(
      `Session "${args.session}" has no daemon socket. The browser daemon may have crashed. Close and reopen the session: libretto close --session ${args.session}`
    );
  }
  args.logger.info("compact-snapshot-via-daemon", {
    session: args.session,
    pageId: args.pageId,
    ref: args.ref
  });
  const client = await DaemonClient.connect(args.daemonSocketPath);
  let result;
  try {
    result = await client.snapshot({
      pageId: args.pageId,
      useCachedSnapshot: args.ref !== void 0
    });
  } finally {
    client.destroy();
  }
  console.log(`Screenshot at ${result.pngPath}`);
  console.log(renderSnapshot(result.snapshot, args.ref));
  console.log(
    `Hint: Use libretto snapshot <ref> --session ${args.session} to inspect a subtree.`
  );
}
const snapshotInput = SimpleCLI.input({
  positionals: [
    SimpleCLI.positional("ref", z.string().optional(), {
      help: "Optional element ref to scope output to that subtree (for example, l16 or e16)"
    })
  ],
  named: {
    session: sessionOption(),
    page: pageOption(),
    objective: SimpleCLI.option(z.string().optional()),
    context: SimpleCLI.option(z.string().optional())
  }
});
const snapshotCommand = SimpleCLI.command({
  description: "Capture a screenshot and compact accessibility snapshot"
}).input(snapshotInput).use(withRequiredSession()).handle(async ({ input, ctx }) => {
  await runCompactSnapshot({
    session: ctx.session,
    daemonSocketPath: ctx.sessionState.daemonSocketPath,
    logger: ctx.logger,
    pageId: input.page,
    ref: input.ref
  });
});
export {
  FALLBACK_SNAPSHOT_VIEWPORT,
  forceSnapshotViewport,
  isZeroViewport,
  isZeroWidthScreenshotError,
  readSnapshotViewportMetrics,
  resolveSnapshotViewport,
  shouldForceSnapshotViewport,
  snapshotCommand,
  snapshotInput
};
